#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Simulate sequential write, append, and extraction
    std::stringstream stream;

    // 1. Initial write (equivalent to ios::out)
    stream << "Dallas" << " " << "Houston" << " " << "Atlanta" << " ";

    // 2. Append additional data (equivalent to ios::out | ios::app)
    stream.seekp(0, std::ios::end);
    stream << "Savannah" << " " << "Austin" << " " << "Chicago";

    // 3. Read back data idiomatically
    std::string city;
    bool first = true;
    while (stream >> city) {
        if (!first) {
            std::cout << " ";
        }
        std::cout << city;
        first = false;
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

void showState(const std::istream& stream) {
    std::cout << "Stream status:" << std::endl;
    std::cout << "  eof(): " << stream.eof() << std::endl;
    std::cout << "  fail(): " << stream.fail() << std::endl;
    std::cout << "  bad(): " << stream.bad() << std::endl;
    std::cout << "  good(): " << stream.good() << std::endl;
}

int main() {
    // 1. Normal operation with a populated stream
    std::istringstream stream("Dallas");
    std::cout << "Normal operation (no errors)" << std::endl;
    showState(stream);

    // 2. Read string to trigger EOF (read full content up to end)
    std::string city;
    stream >> city;
    std::cout << "End of file (no errors)" << std::endl;
    showState(stream);

    // 3. Attempt to read past EOF (triggers failbit)
    stream >> city;
    std::cout << "Bad operation (errors)" << std::endl;
    showState(stream);

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Emulate Listing 13.10 BinaryCharOutput.cpp using binary stringstream
    std::stringstream binaryio(std::ios::in | std::ios::out | std::ios::binary);

    std::string s = "Atlanta";

    // Write raw byte sequence to binary stream
    binaryio.write(s.c_str(), static_cast<std::streamsize>(s.size()));

    // Verify written binary content
    std::string writtenData = binaryio.str();
    std::cout << "Bytes written: " << writtenData.size() << std::endl;
    std::cout << "Content: " << writtenData << std::endl;
    std::cout << "Done" << std::endl;

    return 0;
}
